/**
 * Microsoft Excel (SharePoint) Node - Version 1
 * Discriminator: resource=worksheet, operation=update
 */


interface Credentials {
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Update rows matched by a column value */
export type MicrosoftExcelSharePointV1WorksheetUpdateParams = {
  resource: 'worksheet';
  operation: 'update';
  authentication?: 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * Pick the workbook by URL (no site or library needed), from the list, or by ID
 * @searchListMethod searchWorkbooks
 * @default {"mode":"url","value":""}
 */
    workbook?: { __rl: true; mode: 'url' | 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The SharePoint site the workbook lives in. Only needed when the workbook is chosen from the list or by ID.
 * @searchListMethod searchSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * The document library the workbook lives in. Only needed when the workbook is chosen from the list or by ID.
 * @searchListMethod searchLibraries
 * @default {"mode":"list","value":""}
 */
    library?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Sheet
 * @searchListMethod getSheets
 * @default {"mode":"list","value":""}
 */
    worksheet?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Select a Range
 * @default false
 */
    useRange?: boolean | Expression<boolean>;
/**
 * The sheet range to read the data from specified using a A1-style notation, has to be specific e.g A1:B5, generic ranges like A:B are not supported. Leave blank to use whole used range in the sheet.
 * @hint First row must contain column names
 * @displayOptions.show { useRange: [true] }
 */
    range?: string | Expression<string>;
/**
 * Data Mode
 * @default define
 */
    dataMode?: 'autoMap' | 'define' | 'raw' | Expression<string>;
/**
 * Raw values for the specified range as array of string arrays in JSON format
 * @hint Without a range, the data must match the sheet's used range dimensions exactly
 * @displayOptions.show { dataMode: ["raw"] }
 */
    data?: IDataObject | string | Expression<string>;
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @hint Used to find the correct row to update. Doesn't get changed.
 * @loadOptionsMethod getWorksheetColumnRow
 * @displayOptions.show { dataMode: ["autoMap", "define"] }
 */
    columnToMatchOn?: string | Expression<string>;
/**
 * Value of Column to Match On
 * @displayOptions.show { dataMode: ["define"] }
 */
    valueToMatchOn?: string | Expression<string>;
/**
 * Values to Send
 * @displayOptions.show { dataMode: ["define"] }
 * @default {}
 */
    fieldsUi?: {
        /** Field
     */
    values?: Array<{
      /** Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
       * @loadOptionsMethod getWorksheetColumnRowSkipColumnToMatchOn
       */
      column?: string | Expression<string>;
      /** Value
       */
      fieldValue?: string | Expression<string>;
    }>;
  };
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether the data should be returned RAW instead of parsed into keys according to their header
     * @default 0
     */
    rawData?: boolean | Expression<boolean>;
    /** The name of the property into which to write the RAW data
     * @displayOptions.show { rawData: [true] }
     * @default data
     */
    dataProperty?: string | Expression<string>;
    /** Fields to include in the response. Separate multiple fields with a comma.
     * @displayOptions.show { rawData: [true] }
     */
    fields?: string | Expression<string>;
    /** Whether to update all matching rows or just the first match
     * @displayOptions.hide { /dataMode: ["raw"] }
     * @default false
     */
    updateAll?: boolean | Expression<boolean>;
  };
};

export type MicrosoftExcelSharePointV1WorksheetUpdateNode = {
  type: 'n8n-nodes-base.microsoftExcelSharePoint';
  version: 1;
  config: NodeConfig<MicrosoftExcelSharePointV1WorksheetUpdateParams> & { credentials?: Credentials };
};